const getHighResImage = (post, width, height) => {
    let imgUrl = null;
    if (post.media$thumbnail) {
        imgUrl = post.media$thumbnail.url;
    } else if (post.content && post.content.$t.match(/<img.+?src="([^"]+)"/)) {
        imgUrl = post.content.$t.match(/<img.+?src="([^"]+)"/)[1];
    }
    if (!imgUrl) return '[[PLACEHOLDER_IMG]]';
    imgUrl = imgUrl.replace(/\/(s|w|h)\d+.*?(\/)/g, `/w${width}-h${height}-c$2`);
    imgUrl = imgUrl.replace(/=(s|w|h)\d+.*$/g, `=w${width}-h${height}-c`);
    return imgUrl;
};

const magCardHtml = (post, width, height) => {
    const link = post.link.find(l => l.rel === 'alternate').href;
    const title = post.title.$t;
    const img = getHighResImage(post, width, height);
    const badge = (post.category && post.category[0]) ? post.category[0].term : 'Destaque';
    return `<a href="${link}" class="mag-card h-100 d-block">
        <img src="${img}" class="mag-img" alt="${title}" loading="lazy">
        <div class="mag-overlay">
            <span class="mag-badge">${badge}</span>
            <h3 class="mag-title h5 mb-0 text-white">${title}</h3>
        </div>
    </a>`;
};

const fetchMagazinePosts = async (containerId, maxResults, layoutType, label = '') => {
    const container = document.getElementById(containerId);
    if (!container) return;
    container.innerHTML = '<div class="d-flex justify-content-center py-5"><div class="spinner-grow text-primary" role="status"></div></div>';
    let feedUrl = `/feeds/posts/default?alt=json&max-results=${maxResults}`;
    if (label !== '') feedUrl = `/feeds/posts/default/-/${label}?alt=json&max-results=${maxResults}`;
    try {
        const response = await fetch(feedUrl);
        if (!response.ok) throw new Error('Falha na rede');
        const data = await response.json();
        const posts = data.feed.entry || [];
        if (!posts.length) { container.innerHTML = ''; return; }

        let html = '';
        if (layoutType === 'hero') {
            const first = posts[0];
            const resto = posts.slice(1, 3);
            html += '<div class="row g-3">';
            html += `<div class="col-lg-6" style="min-height:360px">${magCardHtml(first, 800, 600)}</div>`;
            html += '<div class="col-lg-6"><div class="row g-3 h-100">';
            resto.forEach(post => {
                html += `<div class="col-md-6" style="min-height:170px">${magCardHtml(post, 500, 350)}</div>`;
            });
            html += '</div></div></div>';
        } else {
            html += '<div class="row g-3">';
            posts.forEach(post => {
                html += `<div class="col-md-3" style="min-height:220px">${magCardHtml(post, 400, 300)}</div>`;
            });
            html += '</div>';
        }
        container.innerHTML = html;
    } catch (error) {
        container.innerHTML = '<div class="alert alert-danger border-0 border-start border-danger border-4">Falha ao carregar artigos.</div>';
    }
};

if (window.location.pathname === '/' || window.location.pathname === '/index.html') {
    fetchMagazinePosts('js-hero-grid', 3, 'hero');
    // Exemplos para seções por categoria:
    // fetchMagazinePosts('mag-block-1', 4, 'grid', 'Tecnologia');
    // fetchMagazinePosts('mag-block-2', 4, 'grid');
}

