document.addEventListener('DOMContentLoaded', function() {
    const cookieBanner = document.getElementById('vm-cookie-banner');
    const acceptBtn = document.getElementById('vm-cookie-accept');
    if (!cookieBanner || !acceptBtn) return;
    const hasConsented = localStorage.getItem('vm-cookie-consent');
    if (!hasConsented) {
        setTimeout(() => {
            cookieBanner.style.display = 'block';
            void cookieBanner.offsetWidth; // Reflow — força o browser a registar display:block antes da animação
            cookieBanner.classList.add('show-banner');
        }, 1000);
    }
    acceptBtn.addEventListener('click', function() {
        localStorage.setItem('vm-cookie-consent', 'accepted');
        cookieBanner.classList.remove('show-banner');
        setTimeout(() => { cookieBanner.style.display = 'none'; }, 500);
    });
});

